SELECT COUNT(*)
FROM travel_plan_item_alternatives
WHERE travel_plan_item_id = #{travelPlanItemId}

SELECT id, travel_plan_item_id, alternative_order, condition_label, content, tag,
       created_by_member_id, version, created_at, updated_at
FROM travel_plan_item_alternatives
WHERE id = #{id}
  AND travel_plan_item_id = #{travelPlanItemId}

SELECT id, travel_plan_item_id, alternative_order, condition_label, content, tag,
       created_by_member_id, version, created_at, updated_at
FROM travel_plan_item_alternatives
WHERE travel_plan_item_id = #{travelPlanItemId}
  AND alternative_order = #{alternativeOrder}

mapper.insert:
INSERT INTO travel_plan_item_alternatives (
    travel_plan_item_id, alternative_order, condition_label, content, tag,
    created_by_member_id
) VALUES (
    #{travelPlanItemId}, #{alternativeOrder}, #{conditionLabel}, #{content}, #{tag},
