)

mapper.update:
UPDATE travel_plan_item_alternatives
SET condition_label = #{conditionLabel},
    content = #{content},
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND travel_plan_item_id = #{travelPlanItemId}
  AND version = #{version}

